import { fileURLToPath } from "node:url";

const root = path.dirname(fileURLToPath(import.meta.url));
const schemaText = fs.readFileSync(path.join(root, "service-wire-v1.schema.json"), "utf8");
const schema = JSON.parse(schemaText);
const hash = crypto.createHash("sha256").update(schemaText).digest("hex");
const check = process.argv.includes("--check");
const actorJoin = schema.commands.find((command) => command.id === 28 && command.name === "actorJoin");
const relocation = schema.relocationLogicalStreamFormat;
const relocationFixture = JSON.parse(fs.readFileSync(
  path.join(root, "golden/relocation-envelope-v1.json"), "utf8",
));
const relocationDataChunkFixture = JSON.parse(fs.readFileSync(
  path.join(root, "golden/relocation-data-chunk-v1.json"), "utf8",
));
const relocationManifestFixture = JSON.parse(fs.readFileSync(
  path.join(root, "golden/relocation-manifest-v1.json"), "utf8",
));
const actorJoinFixture = JSON.parse(fs.readFileSync(
  path.join(root, "golden/actor-join-request-v1.json"), "utf8",
));
const getType = (name) => {
  const found = schema.types.find((type) => type.name === name);
  if (!found) throw new Error(`type ${name} missing from schema`);
  return found;
};
const getDurableFormat = (name) => {
  const found = schema.durableFormats.find((format) => format.name === name);
  if (!found) throw new Error(`durable format ${name} missing from schema`);
  return found;
};
const textTypes = schema.types.filter((type) => type.kind === "length-prefixed-text");
