	function readFence(bytes: Uint8Array, at: { value: number }): ServiceWireRouteFence { const value={ id:readText8(bytes,at), generation:read64(bytes,at), targetNodeRid:readRid(bytes,at), targetNodeGeneration:read64(bytes,at), expectedAuthorityOwnerGeneration:read64(bytes,at), expectedOwnerLeaseGeneration:read64(bytes,at) };if(!value.generation||!value.targetNodeGeneration||!value.expectedAuthorityOwnerGeneration||!value.expectedOwnerLeaseGeneration)throw new RangeError("invalid fence");return value; }
